import{_ as i,a0 as p,w as r,s as d,ao as l,I as s,x as o,a1 as u,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Tuxedo 已對所有用户開放基於 Ubuntu 的 TUXEDO OS | LCTT x X-CMD","titleTemplate":false,"description":"Tuxedo 已對所有用户開放基於 Ubuntu 的 TUXEDO OS | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Tuxedo 已對所有用户開放基於 Ubuntu 的 TUXEDO OS | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Tuxedo 已對所有用户開放基於 Ubuntu 的 TUXEDO OS | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20220930 [Exclusive] Tuxedo Makes Ubuntu-based -TUXEDO OS- Available For All","title":"Tuxedo 已對所有用户開放基於 Ubuntu 的 TUXEDO OS","tag":"202210","desc":""},"relativePath":"202210/20220930 [Exclusive] Tuxedo Makes Ubuntu-based -TUXEDO OS- Available For All.md","filePath":"[post].md"}'),T={name:"202210/20220930 [Exclusive] Tuxedo Makes Ubuntu-based -TUXEDO OS- Available For All.md"};function a(O,t,x,U,m,D){const e=p("Link");return r(),d("div",null,[t[31]||(t[31]=l('<h1 id="tuxedo-已對所有用户開放基於-ubuntu-的-tuxedo-os" tabindex="-1">Tuxedo 已對所有用户開放基於 Ubuntu 的 TUXEDO OS <a class="header-anchor" href="#tuxedo-已對所有用户開放基於-ubuntu-的-tuxedo-os" aria-label="Permalink to “Tuxedo 已對所有用户開放基於 Ubuntu 的 TUXEDO OS”">​</a></h1><blockquote><p>TUXEDO OS 是一個基於 Ubuntu 的 Linux 發行版，旨在將 TUXEDO 在 Linux 方面的專業知識也帶給非 TUXEDO 用户。</p></blockquote><p><img src="https://news.itsfoss.com/content/images/size/w1200/2022/09/tuxedo-os-1.png" alt="[獨家] Tuxedo 已對所有用户開放基於 Ubuntu 的 &#39;TUXEDO OS&#39;"></p><p>又一個基於 Ubuntu 的 Linux 發行版？😕</p><p>不完全是！<strong>TUXEDO 計算機公司</strong> 是一家硬件製造商，以其專注於 Linux 的筆記本電腦和計算機而聞名。</p><p><strong>TUXEDO OS 與 Ubuntu 之間存在着一些有趣的差異</strong>。</p><p>雖然他們已經在筆記本電腦/計算機上提供預裝 TUXEDO OS 的選項，但是它並未對所有人開放。</p><p>終於，他們決定將其發行版的第一個版本作為 <strong>TUXEDO OS 1</strong> 開放，該版本現已可供下載。</p><p>這也意味着你可以在自己的非 TUXEDO 系統上試用它。</p><p>所以這個思路很像 System76 的 Pop!_OS，所以這並不算一件壞事 👌</p><h3 id="搭配-kde-的-tuxedo-os-1" tabindex="-1">搭配 KDE 的 TUXEDO OS 1 <a class="header-anchor" href="#搭配-kde-的-tuxedo-os-1" aria-label="Permalink to “搭配 KDE 的 TUXEDO OS 1”">​</a></h3><p><img src="https://news.itsfoss.com/content/images/2022/09/tuxedo-home.jpg" alt="tuxedo 桌面"></p>',12)),s("p",null,[t[1]||(t[1]=o("TUXEDO OS 1 是基於 ",-1)),u(e,{href:"https://news.itsfoss.com/ubuntu-22-04-release/"},{default:n(()=>[...t[0]||(t[0]=[o("Ubuntu 22.04 LTS",-1)])]),_:1}),t[2]||(t[2]=o(" 的; 所以它應該可以直接在大多數設備上運行。",-1))]),s("p",null,[t[4]||(t[4]=o("與 System76 的 Pop!_OS 不同，TUXEDO OS 搭載了 ",-1)),u(e,{href:"https://news.itsfoss.com/kde-plasma-5-24-lts-release/"},{default:n(()=>[...t[3]||(t[3]=[o("KDE Plasma 5.24.6",-1)])]),_:1}),t[5]||(t[5]=o("。因此，它應當提供了一個 Windows 用户也較為熟悉的用户界面。",-1))]),t[32]||(t[32]=l('<p>但是，TUXEDO OS 還包括一些額外的功能，例如 TUXEDO 控制中心，用於微調你的硬件（CPU/風扇等），以及 TUXEDO Tomte，一個用於解決驅動程序/缺少包問題的配置服務，但是它或許能，或許不能在其他硬件配置上工作。</p><p>説到這裏，讓我們看看 TUXEDO OS 及其提供的功能。</p><h3 id="tuxedo-os-基於-kde-的定製化-ubuntu-體驗" tabindex="-1">TUXEDO OS，基於 KDE 的定製化 Ubuntu 體驗 <a class="header-anchor" href="#tuxedo-os-基於-kde-的定製化-ubuntu-體驗" aria-label="Permalink to “TUXEDO OS，基於 KDE 的定製化 Ubuntu 體驗”">​</a></h3><p>用户體驗正如預期一樣，與任何基於 KDE 的 Ubuntu 發行版相同。</p><blockquote><p>📣 我將 TUXEDO OS（預覽版）用做我的主要系統來體驗它。</p></blockquote><p>你會在應用和菜單上發現帶有紅色調的 TUXEDO 徽標。它還具有令人耳目一新的壁紙。</p><p><img src="https://news.itsfoss.com/content/images/2022/09/tuxedo-menu.png" alt="tuxedo 菜單"></p><p>除了定製化的 KDE Plasma 主題，還有一些其他的變化，例如：</p><ul><li>它使用了 PipeWire 作為聲音服務器，而不是 PulseAudio。</li><li>GRUB 中啓用了 os-prober 功能，讓用户可以方便地檢測已安裝的其他操作系統。</li><li>.deb 作為首選的軟件包格式，而 Snap 默認情況下被禁用。</li><li>從 NetworkManagerConnectivity 檢查中移除了 Canonical 的鏈接。</li></ul><h4 id="軟件可用性" tabindex="-1">軟件可用性？ <a class="header-anchor" href="#軟件可用性" aria-label="Permalink to “軟件可用性？”">​</a></h4><p>你可以通過 “<ruby>發現<rt>Discover</rt></ruby>” 應用來找到所有流行的軟件工具，其中包括 Ubuntu 的倉庫和 TUXEDO 的倉庫。</p><p>它包含了 <strong>Firefox、Thunderbird、LibreOffice、VLC、Lutris 和 Heroic Games Launcher</strong> 等必備應用程序。所以我認為你不會覺得它們很臃腫。</p><p><img src="https://news.itsfoss.com/content/images/2022/09/tuxedo-os-repositories.png" alt="tuxedo discover 應用"></p><p>我還注意到它默認啓用了 Flatpak 集成。</p>',14)),s("p",null,[t[7]||(t[7]=o("你可以在他們的 ",-1)),u(e,{href:"https://www.tuxedocomputers.com/en/Featured-KDEs-outstanding-applications-and-tools.tuxedo"},{default:n(()=>[...t[6]||(t[6]=[o("官方網頁",-1)])]),_:1}),t[8]||(t[8]=o(" 上了解有關可用軟件的更多信息。",-1))]),t[33]||(t[33]=s("h4",{id:"這也給我們帶來了一個重要的亮點",tabindex:"-1"},[o("這也給我們帶來了一個重要的亮點 "),s("a",{class:"header-anchor",href:"#這也給我們帶來了一個重要的亮點","aria-label":"Permalink to “這也給我們帶來了一個重要的亮點”"},"​")],-1)),t[34]||(t[34]=s("p",null,"❌ TUXEDO OS 不會默認安裝 Snap。對於 Firefox，它會像 Linux Mint 一樣附帶 deb 包安裝。",-1)),t[35]||(t[35]=s("p",null,"✅ 值得注意的是，TUXEDO OS 22.04 LTS 附帶了 Nvidia 驅動程序。",-1)),t[36]||(t[36]=s("p",null,"因此，我可以毫不費力地將它安裝在帶有 RTX 3060 Ti 顯卡的系統上。",-1)),t[37]||(t[37]=s("h3",{id:"tuxedo-附加功能",tabindex:"-1"},[o("TUXEDO 附加功能 "),s("a",{class:"header-anchor",href:"#tuxedo-附加功能","aria-label":"Permalink to “TUXEDO 附加功能”"},"​")],-1)),t[38]||(t[38]=s("p",null,"如上所述，TUXEDO OS 附帶了一些專為增強 Tuxedo 硬件的體驗而量身定製的附加功能。",-1)),s("p",null,[t[10]||(t[10]=o("控制中心是監控你的系統、選擇電源配置文件、控制外部水冷（",-1)),u(e,{href:"https://www.tuxedocomputers.com/en/TUXEDO-Aquaris.tuxedo"},{default:n(()=>[...t[9]||(t[9]=[o("TUXEDO Aquaris",-1)])]),_:1}),t[11]||(t[11]=o("）等的絕佳工具。",-1))]),t[39]||(t[39]=l('<p><img src="https://news.itsfoss.com/content/images/2022/09/tuxedo-os-control-center.png" alt="tuxedo 控制中心"></p><p>雖然控制中心不是為非 TUXEDO 設備量身定製的，但它在大多數情況下仍然能夠正常工作。</p><p>還有一個 TUXEDO WebFAI Creator 程序（定製的 BalenaEtcher）來燒錄用於操作系統安裝的 U 盤。</p><p><img src="https://news.itsfoss.com/content/images/2022/09/tuxedo-webfai.jpg" alt="tuxedo webfai"></p><p>還有，不要忘記 TUXEDO Tomte，它無法在我的系統上運行，但可以很完美的在 TUXEDO 設備上作為配置服務運行：</p><p><img src="https://news.itsfoss.com/content/images/2022/09/tuxedo-tomte.jpg" alt=""></p><h3 id="下載-tuxedo-os-1" tabindex="-1">下載 TUXEDO OS 1 <a class="header-anchor" href="#下載-tuxedo-os-1" aria-label="Permalink to “下載 TUXEDO OS 1”">​</a></h3><p>TUXEDO OS 帶來了非常精緻的體驗。TUXEDO 背後的團隊在讓 Linux 運行在他們的一些最新筆記本電腦上擁有豐富的經驗。因此，使用他們的 Linux 發行版，你可以對自己的體驗充滿信心。</p>',8)),s("p",null,[t[13]||(t[13]=o("如果你有興趣，還可以找到關於 ",-1)),u(e,{href:"https://www.tuxedocomputers.com/en/First-Steps-with-TUXEDO-OS.tuxedo"},{default:n(()=>[...t[12]||(t[12]=[o("TUXEDO OS 入門",-1)])]),_:1}),t[14]||(t[14]=o(" 的官方文章。",-1))]),t[40]||(t[40]=s("p",null,[s("strong",null,"如果你希望獲得一個基於 KDE 的定製化 Ubuntu 體驗，TUXEDO OS 1 是一個不錯的選擇。")],-1)),t[41]||(t[41]=s("p",null,"你可以通過使用它來支持他們的計劃，這可能會讓你決定購買一台 TUXEDO 設備；你永遠不知道以後會發生什麼，對吧？",-1)),t[42]||(t[42]=s("p",null,"你可以從其官方網站下載它，並在下方的評論區中分享你的想法。",-1)),s("blockquote",null,[s("p",null,[s("strong",null,[u(e,{href:"https://www.tuxedocomputers.com/os"},{default:n(()=>[...t[15]||(t[15]=[o("下載 TUXEDO OS 1",-1)])]),_:1})])])]),t[43]||(t[43]=s("hr",null,null,-1)),s("p",null,[t[17]||(t[17]=o("via: ",-1)),u(e,{href:"https://news.itsfoss.com/tuxedo-os/"},{default:n(()=>[...t[16]||(t[16]=[o("https://news.itsfoss.com/tuxedo-os/",-1)])]),_:1})]),s("p",null,[t[22]||(t[22]=o("作者：",-1)),u(e,{href:"https://news.itsfoss.com/author/ankush/"},{default:n(()=>[...t[18]||(t[18]=[o("Ankush Das",-1)])]),_:1}),t[23]||(t[23]=o(" 選題：",-1)),u(e,{href:"https://github.com/lkxed"},{default:n(()=>[...t[19]||(t[19]=[o("lkxed",-1)])]),_:1}),t[24]||(t[24]=o(" 譯者：",-1)),u(e,{href:"https://github.com/Cubik65536"},{default:n(()=>[...t[20]||(t[20]=[o("Cubik65536",-1)])]),_:1}),t[25]||(t[25]=o(" 校對：",-1)),u(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[21]||(t[21]=[o("wxy",-1)])]),_:1})]),s("p",null,[t[28]||(t[28]=o("本文由 ",-1)),u(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[26]||(t[26]=[o("LCTT",-1)])]),_:1}),t[29]||(t[29]=o(" 原創編譯，",-1)),u(e,{href:"https://linux.cn/"},{default:n(()=>[...t[27]||(t[27]=[o("Linux中國",-1)])]),_:1}),t[30]||(t[30]=o(" 榮譽推出",-1))])])}const X=i(T,[["render",a]]);export{f as __pageData,X as default};
